INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b5e69546-2d9f-4b03-9a62-224c77defd11', 'a1a1a1a1-3030-4000-8000-000000000001', 13, 'Dia 13 — Perdão', 'Semana 2: Desconstruir', '{"pch": "Perdoem como o Senhor perdoou voc\u00eas\u2026 O perd\u00e3o n\u00e3o \u00e9 sentimento \u2014 \u00e9 decis\u00e3o.", "verse": "Cl 3,13", "lectio": "Leia Cl 3,12-17. Revestir-se de compaix\u00e3o.", "practice": "Escreva o nome de quem precisa perdoar. Reze por essa pessoa.", "question": "Quem voc\u00ea ainda n\u00e3o perdoou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a33cfda2-79e6-40b2-b690-0c22e1890abb', 'a1a1a1a1-3030-4000-8000-000000000001', 14, 'Dia 14 — Silêncio', 'Semana 2: Desconstruir', '{"pch": "Aquietai-vos e sabei que Eu sou Deus\u2026 No barulho, voc\u00ea se perde. No sil\u00eancio, se encontra.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio no meio do caos.", "practice": "10 minutos de sil\u00eancio contemplativo antes de dormir.", "question": "O que o barulho da sua rotina esconde?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3c7aeb85-1858-467c-975d-a666e9d8ebd0', 'a1a1a1a1-3030-4000-8000-000000000001', 15, 'Dia 15 — Visão', 'Semana 3: Reconstruir', '{"pch": "Escreve a vis\u00e3o\u2026 e torna-a clara. O que n\u00e3o est\u00e1 escrito, n\u00e3o se realiza.", "verse": "Hc 2,2", "lectio": "Leia Hc 2,1-4. A vis\u00e3o tem tempo certo.", "practice": "Escreva sua vis\u00e3o de vida em 1 par\u00e1grafo.", "question": "Qual sua vis\u00e3o para os pr\u00f3ximos 5 anos?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('12e661ac-582e-4c7b-8899-2ac42118bf80', 'a1a1a1a1-3030-4000-8000-000000000001', 16, 'Dia 16 — Valores', 'Semana 3: Reconstruir', '{"pch": "Onde est\u00e1 o teu tesouro\u2026 a\u00ed est\u00e1 o teu cora\u00e7\u00e3o. O que voc\u00ea valoriza define quem voc\u00ea \u00e9.", "verse": "Mt 6,21", "lectio": "Leia Mt 6,19-24. Tesouro no c\u00e9u vs. tesouro na terra.", "practice": "Liste seus 5 valores mais importantes. Veja se sua vida reflete isso.", "question": "Quais s\u00e3o seus 3 valores inegoci\u00e1veis?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('2e987379-972e-47a4-bcb1-a2ecad2d45c5', 'a1a1a1a1-3030-4000-8000-000000000001', 17, 'Dia 17 — Decisão', 'Semana 3: Reconstruir', '{"pch": "Escolhei hoje a quem servireis\u2026 A indecis\u00e3o tamb\u00e9m \u00e9 uma escolha.", "verse": "Js 24,15", "lectio": "Leia Js 24,14-18. Josu\u00e9 decidiu por toda sua casa.", "practice": "Tome uma decis\u00e3o que est\u00e1 pendente. Qualquer uma. Agora.", "question": "Que decis\u00e3o voc\u00ea est\u00e1 adiando?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7c61db8f-303e-4621-83e3-09bac050ac36', 'a1a1a1a1-3030-4000-8000-000000000001', 18, 'Dia 18 — Disciplina', 'Semana 3: Reconstruir', '{"pch": "Disciplino o meu corpo\u2026 Sem disciplina, o prop\u00f3sito vira apenas desejo.", "verse": "1Cor 9,27", "lectio": "Leia 1Cor 9,24-27. Paulo corria para vencer.", "practice": "Escolha 1 h\u00e1bito pequeno e pratique por 7 dias consecutivos.", "question": "Em que \u00e1rea da sua vida falta disciplina?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1976d29-1635-4597-a295-21fb26c1cdcb', 'a1a1a1a1-3030-4000-8000-000000000001', 19, 'Dia 19 — Coragem', 'Semana 3: Reconstruir', '{"pch": "S\u00ea forte e corajoso\u2026 porque o Senhor est\u00e1 contigo. Coragem n\u00e3o \u00e9 aus\u00eancia de medo.", "verse": "Js 1,9", "lectio": "Leia Js 1,1-9. Deus repetiu: s\u00ea forte.", "practice": "Fa\u00e7a uma coisa que te assusta hoje \u2014 mesmo pequena.", "question": "O que voc\u00ea faria se n\u00e3o tivesse medo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bb65465d-4947-48f6-9d6c-a18dbca31406', 'a1a1a1a1-3030-4000-8000-000000000001', 20, 'Dia 20 — Serviço', 'Semana 3: Reconstruir', '{"pch": "O Filho do Homem veio para servir\u2026 Prop\u00f3sito n\u00e3o \u00e9 sobre voc\u00ea \u2014 \u00e9 sobre quem voc\u00ea serve.", "verse": "Mc 10,45", "lectio": "Leia Mc 10,42-45. A lideran\u00e7a \u00e9 servi\u00e7o.", "practice": "Fa\u00e7a algo por algu\u00e9m hoje sem esperar nada em troca.", "question": "Quem se beneficia quando voc\u00ea vive seu melhor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('282a548d-3009-4cf5-aa5d-0f01aa82aac2', 'a1a1a1a1-3030-4000-8000-000000000001', 21, 'Dia 21 — Identidade em Cristo', 'Semana 3: Reconstruir', '{"pch": "Se algu\u00e9m est\u00e1 em Cristo\u2026 \u00e9 nova criatura. Sua identidade n\u00e3o est\u00e1 no que voc\u00ea faz, mas em quem voc\u00ea \u00e9.", "verse": "2Cor 5,17", "lectio": "Leia 2Cor 5,14-21. Embaixadores de Cristo.", "practice": "Escreva: Eu sou ______ em Cristo. Complete 5 vezes.", "question": "Quem voc\u00ea \u00e9 quando ningu\u00e9m est\u00e1 vendo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6f54e6e9-2b46-44e2-aca6-1efbebe2d0e3', 'a1a1a1a1-3030-4000-8000-000000000001', 22, 'Dia 22 — Presença', 'Semana 4: Integrar', '{"pch": "Na tua presen\u00e7a h\u00e1 plenitude de alegria\u2026 Prop\u00f3sito come\u00e7a quando voc\u00ea est\u00e1 presente.", "verse": "Sl 16,11", "lectio": "Leia Sl 16. Deus \u00e9 a por\u00e7\u00e3o da heran\u00e7a.", "practice": "Viva hoje com aten\u00e7\u00e3o plena. Observe cada momento.", "question": "Em que momentos voc\u00ea se sente mais presente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6994196f-8d3c-4b7f-a609-4c26f0acc649', 'a1a1a1a1-3030-4000-8000-000000000001', 23, 'Dia 23 — Missão', 'Semana 4: Integrar', '{"pch": "Ide e fazei disc\u00edpulos\u2026 Sua vida \u00e9 sua maior mensagem.", "verse": "Mt 28,19", "lectio": "Leia Mt 28,16-20. A grande comiss\u00e3o.", "practice": "Escreva sua declara\u00e7\u00e3o de miss\u00e3o pessoal em 1 frase.", "question": "Se sua vida fosse uma mensagem, qual seria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b359357b-7017-498f-b4a5-ed558f7e910c', 'a1a1a1a1-3030-4000-8000-000000000001', 24, 'Dia 24 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor de todo o cora\u00e7\u00e3o\u2026 e Ele endireitar\u00e1 as tuas veredas.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. Sabedoria vs. entendimento pr\u00f3prio.", "practice": "Entregue em ora\u00e7\u00e3o a \u00e1rea mais dif\u00edcil da sua vida.", "question": "Em que \u00e1rea voc\u00ea ainda n\u00e3o confiou a Deus?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('eed9da3a-776e-4f1d-a458-c9d651b640ca', 'a1a1a1a1-3030-4000-8000-000000000001', 25, 'Dia 25 — Perseverança', 'Semana 4: Integrar', '{"pch": "N\u00e3o nos cansemos de fazer o bem\u2026 porque a seu tempo colheremos. O prop\u00f3sito exige const\u00e2ncia.", "verse": "Gl 6,9", "lectio": "Leia Gl 6,7-10. A lei da semeadura.", "practice": "Retome algo que abandonou. D\u00ea mais um passo.", "question": "Em que voc\u00ea j\u00e1 desistiu cedo demais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('abc5e0a3-7d65-4411-92c6-1bcd1dbadc5c', 'a1a1a1a1-3030-4000-8000-000000000001', 26, 'Dia 26 — Comunidade', 'Semana 4: Integrar', '{"pch": "Melhor \u00e9 serem dois do que um\u2026 Prop\u00f3sito isolado definha. Prop\u00f3sito compartilhado floresce.", "verse": "Ec 4,9-10", "lectio": "Leia Ec 4,9-12. A corda de tr\u00eas dobras.", "practice": "Convide algu\u00e9m para compartilhar sua jornada espiritual.", "question": "Quem caminha com voc\u00ea? Quem deveria caminhar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('30bfc644-7672-461d-9694-0a1b3b0f00a1', 'a1a1a1a1-3030-4000-8000-000000000001', 27, 'Dia 27 — Legado', 'Semana 4: Integrar', '{"pch": "Combati o bom combate\u2026 completei a carreira. O que ficar\u00e1 quando voc\u00ea partir?", "verse": "2Tm 4,7", "lectio": "Leia 2Tm 4,6-8. Paulo olha para tr\u00e1s com paz.", "practice": "Escreva o que voc\u00ea quer que digam no seu funeral.", "question": "Que legado voc\u00ea quer deixar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4368c10d-fe86-468f-a43d-da8518d4ad35', 'a1a1a1a1-3030-4000-8000-000000000001', 28, 'Dia 28 — Gratidão', 'Semana 4: Integrar', '{"pch": "Em tudo dai gra\u00e7as\u2026 A gratid\u00e3o transforma a perspectiva e revela o prop\u00f3sito no cotidiano.", "verse": "1Ts 5,18", "lectio": "Leia 1Ts 5,16-24. Alegria, ora\u00e7\u00e3o e gratid\u00e3o.", "practice": "Escreva 10 motivos de gratid\u00e3o. Releia antes de dormir.", "question": "Pelo que voc\u00ea \u00e9 grato que nunca agradeceu?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('41a28ae5-52b9-407c-90d7-0a03b73b4a2a', 'a1a1a1a1-3030-4000-8000-000000000001', 29, 'Dia 29 — Compromisso', 'Semana 4: Integrar', '{"pch": "Ofere\u00e7am os seus corpos como sacrif\u00edcio vivo\u2026 Prop\u00f3sito sem compromisso \u00e9 fantasia.", "verse": "Rm 12,1", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Escreva 3 compromissos concretos para os pr\u00f3ximos 30 dias.", "question": "Com o que voc\u00ea se compromete a partir de hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('0443b9b4-2ce3-415a-a730-2773c02f45c3', 'a1a1a1a1-3030-4000-8000-000000000001', 30, 'Dia 30 — Envio', 'Semana 4: Integrar', '{"pch": "Eis-me aqui, envia-me! Voc\u00ea n\u00e3o chegou ao fim\u2026 chegou ao come\u00e7o do que nasceu para viver.", "verse": "Is 6,8", "lectio": "Leia Is 6,1-8. A vis\u00e3o, a purifica\u00e7\u00e3o, o envio.", "practice": "Releia todas as suas reflex\u00f5es. Escreva uma carta para o seu eu de 30 dias atr\u00e1s.", "question": "Quem voc\u00ea se tornou nesses 30 dias?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('95b1090e-117c-4fd8-95ab-7b18071641cd', 'a1b2c3d4-0001-4000-8000-000000000001', 1, 'O Amor de Deus por Você', 'Descobrindo que somos amados', '{"bible_ref": "Jo 3,16", "reflection": "Deus nos amou primeiro. Medite sobre o que significa ser amado incondicionalmente."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e6c6deb4-e34a-429d-b30b-b65a615964eb', 'a1b2c3d4-0001-4000-8000-000000000001', 2, 'Primeira Oração', 'Aprendendo a conversar com Deus', '{"prayer": "Pai nosso", "instruction": "Reze lentamente, saboreando cada palavra."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
